#[capability(
    module = "paypal",
    id = "orders-track-create",
    display_name = r##"Add tracking information for an Order."##,
    description = r##"Adds tracking information for an Order."##,
    side_effects = true
)]
pub async fn orders_track_create(input: OrdersTrackCreateInput) -> Result<Order, AgentError> {
    let connection = kit::require_connection(&input._connection, "PAYPAL")?;
    input.request()?.send(connection, "PAYPAL").await
}

impl OrdersTrackCreateInput {
    /// The request this capability sends; the connection supplies host and credentials.
    pub fn request(&self) -> Result<kit::Request, AgentError> {
        let path = format!(
            "/v2/checkout/orders/{id}/track",
            id = kit::encode_path(&self.id)
        );
        let request = kit::Request::new("POST", path);
        request.json_body(
            kit::Body::new()
                .field("capture_id", &self.capture_id)
                .field("carrier", &self.carrier)
                .field_opt("carrier_name_other", &self.carrier_name_other)
                .field_opt("items", &self.items)
                .field_opt("notify_payer", &self.notify_payer)
                .field("tracking_number", &self.tracking_number),
            "PAYPAL",
        )
    }
}

