#[capability(
    module = "paypal",
    id = "orders-trackers-patch",
    display_name = r##"Update or cancel tracking information for an order"##,
    description = r##"Updates or cancels the tracking information for a PayPal order, by ID. Updatable attributes or objects:

Attribute Op Notes
`items` replace Using replace op for `items` will replace the entire `items` object with the value sent in request.
`notify_payer` replace, add
`status` replace Only patching status to CANCELLED is currently supported."##,
    side_effects = true
)]
pub async fn orders_trackers_patch(input: OrdersTrackersPatchInput) -> Result<Value, AgentError> {
    let connection = kit::require_connection(&input._connection, "PAYPAL")?;
    input.request()?.send(connection, "PAYPAL").await
}

impl OrdersTrackersPatchInput {
    /// The request this capability sends; the connection supplies host and credentials.
    pub fn request(&self) -> Result<kit::Request, AgentError> {
        let path = format!(
            "/v2/checkout/orders/{id}/trackers/{tracker_id}",
            id = kit::encode_path(&self.id),
            tracker_id = kit::encode_path(&self.tracker_id)
        );
        let request = kit::Request::new("PATCH", path);
        request.json_opt(&self.body, "PAYPAL")
    }
}

