#[capability(
    module = "paypal",
    id = "trackers-put",
    display_name = r##"Update or cancel tracking information for PayPal transaction"##,
    description = r##"Updates or cancels the tracking information for a PayPal transaction, by ID. To cancel tracking information, call this method and set the status to CANCELLED. For more information, see Update or cancel tracking information."##,
    side_effects = true
)]
pub async fn trackers_put(input: TrackersPutInput) -> Result<Value, AgentError> {
    let connection = kit::require_connection(&input._connection, "PAYPAL")?;
    input.request()?.send(connection, "PAYPAL").await
}

impl TrackersPutInput {
    /// The request this capability sends; the connection supplies host and credentials.
    pub fn request(&self) -> Result<kit::Request, AgentError> {
        let path = format!(
            "/v1/shipping/trackers/{id}",
            id = kit::encode_path(&self.id)
        );
        let request = kit::Request::new("PUT", path);
        request.json_body(
            kit::Body::new()
                .field_opt("carrier", &self.carrier)
                .field_opt("carrier_name_other", &self.carrier_name_other)
                .field_opt("last_updated_time", &self.last_updated_time)
                .field_opt("notify_buyer", &self.notify_buyer)
                .field_opt("shipment_date", &self.shipment_date)
                .field_opt("shipment_direction", &self.shipment_direction)
                .field("status", &self.status)
                .field_opt("tracking_number", &self.tracking_number)
                .field_opt("tracking_number_type", &self.tracking_number_type)
                .field_opt("tracking_url", &self.tracking_url)
                .field("transaction_id", &self.transaction_id),
            "PAYPAL",
        )
    }
}

#[derive(Debug, Serialize, Deserialize, CapabilityInput)]
#[capability_input(display_name = r##"Add tracking information for multiple PayPal transactions"##)]
pub struct TrackersBatchPostInput {
    #[field(skip)]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub _connection: Option<RawConnection>,
    #[field(
        display_name = r##"Trackers"##,
        description = r##"An array of tracking information for shipments."##
    )]
    #[serde(rename = "trackers", default, skip_serializing_if = "Option::is_none")]
    pub trackers: Option<Vec<TrackingTracker>>,
}

#[capability(
    module = "paypal",
    id = "trackers-batch-post",
    display_name = r##"Add tracking information for multiple PayPal transactions"##,
    description = r##"Deprecation notice: Adding tracking details for an order through `/v1/shipping/trackers-batch` is deprecated as its a legacy way of integration. Use the new Orders v2 API to share tracking details with PayPal.Adds tracking information, with or without tracking numbers, for multiple PayPal transactions. Accepts up to 20 tracking IDs. For more information, see Add tracking information with tracking numbers and Add tracking information without tracking numbers."##,
    side_effects = true
)]
pub async fn trackers_batch_post(
    input: TrackersBatchPostInput,
) -> Result<BatchTrackerCollection, AgentError> {
    let connection = kit::require_connection(&input._connection, "PAYPAL")?;
    input.request()?.send(connection, "PAYPAL").await
}

impl TrackersBatchPostInput {
    /// The request this capability sends; the connection supplies host and credentials.
    pub fn request(&self) -> Result<kit::Request, AgentError> {
        let path = String::from("/v1/shipping/trackers-batch");
        let request = kit::Request::new("POST", path);
        request.json_body(
            kit::Body::new().field_opt("trackers", &self.trackers),
            "PAYPAL",
        )
    }
}

